-- plan-first: generated by `npm run guide:content` from content/guide/plan-first.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы заставляете агента сначала разобраться и предложить план, правите этот план и только потом пускаете агента в код.",
  "blocks": [
    {
      "type": "text",
      "text": "Агент пишет код быстрее вас. Поэтому его самая дорогая ошибка — не опечатка, а неверное допущение: он уверенно правит двенадцать файлов, исходя из того, как, по его мнению, устроен проект. Найти такую ошибку в готовом diff долго, а откатывать обидно."
    },
    {
      "type": "text",
      "text": "План до кода переносит спор туда, где он ничего не стоит. Агент сначала читает проект и пишет, что собирается сделать, а вы правите план, пока не тронут ни один файл."
    },
    {
      "type": "compare",
      "before": {
        "label": "Сразу в код",
        "text": "Добавь в API скидку discount_percent и посчитай её в корзине.",
        "note": "Агент сам решит, где хранить скидку, как округлять и чей код это заденет. Узнаете из diff."
      },
      "after": {
        "label": "Сначала план",
        "text": "/plan Добавь в API скидку discount_percent и посчитай её в корзине. Найди всех, кто использует этот API, и скажи, как проверим результат.",
        "note": "Агент покажет, какие файлы затронет, кто зависит от API и как проверит работу. Решения остаются за вами."
      }
    },
    {
      "type": "heading",
      "text": "Режим планирования"
    },
    {
      "type": "text",
      "text": "В Claude Code для этого есть **plan mode**. В нём агент читает файлы, ищет по коду и запускает команды, чтобы разобраться, но не правит исходники: вместо правок он пишет план и ждёт вашего решения."
    },
    {
      "type": "list",
      "items": [
        "**Shift+Tab** переключает режимы по кругу. В режиме планирования внизу экрана появляется `⏸ plan mode on`.",
        "`/plan` включает режим сразу, можно вместе с задачей: `/plan почини вход по ссылке из письма`.",
        "Сессию можно с самого начала открыть в режиме планирования:"
      ]
    },
    {
      "type": "command",
      "code": "claude --permission-mode plan",
      "caption": "Агент ничего не изменит, пока вы не одобрите план."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик в режиме планирования просит добавить скидку в API. Агент изучает код, находит трёх потребителей API и предлагает пересчитывать поле price. Разработчик запрещает менять price, потому что его читает партнёрская выгрузка. Агент переделывает план: новое поле final_price. После одобрения агент правит три файла и прогоняет тесты.",
      "lines": [
        {
          "kind": "command",
          "text": "claude --permission-mode plan",
          "typed": true
        },
        {
          "kind": "meta",
          "text": "Claude Code · ⏸ plan mode on"
        },
        {
          "kind": "prompt",
          "text": "Добавь в API скидку discount_percent и посчитай её в корзине.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Читаю src/api/cart.ts и src/cart/total.ts"
        },
        {
          "kind": "info",
          "text": "API корзины используют: web, mobile, partner-feed"
        },
        {
          "kind": "info",
          "text": "План: price → цена со скидкой, пересчёт в total.ts, тесты"
        },
        {
          "kind": "prompt",
          "text": "price не трогай: его парсит partner-feed. Нужно новое поле.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "План обновлён: новое поле final_price, price без изменений"
        },
        {
          "kind": "prompt",
          "text": "Одобряю.",
          "typed": true
        },
        {
          "kind": "edit",
          "text": "src/api/cart.ts",
          "diff": "+9"
        },
        {
          "kind": "edit",
          "text": "src/cart/total.ts",
          "diff": "+14 −2"
        },
        {
          "kind": "edit",
          "text": "tests/cart-discount.spec.ts",
          "diff": "+48"
        },
        {
          "kind": "pass",
          "text": "npm test — 31 тест пройден"
        },
        {
          "kind": "done",
          "text": "Готово: final_price добавлен, price не изменился."
        }
      ]
    },
    {
      "type": "diagram",
      "name": "plan-loop",
      "caption": "Круг правки плана занимает минуту. Круг правки кода — час и ревью заново."
    },
    {
      "type": "heading",
      "text": "Что читать в плане"
    },
    {
      "type": "list",
      "items": [
        "**Файлы.** Какие будут затронуты и нет ли среди них лишних. Неожиданный файл в списке — повод спросить «зачем».",
        "**Допущения.** Что агент решил сам: формат данных, поведение по умолчанию, кто использует код. Здесь живут дорогие ошибки.",
        "**Проверка.** Как агент докажет, что всё работает: какие тесты добавит и какие команды запустит.",
        "**Границы.** Что он трогать не будет. Если границы не названы, назовите их сами."
      ]
    },
    {
      "type": "text",
      "text": "Решение за вами. Claude Code предложит одобрить план и перейти в режим auto (если он недоступен — принимать правки автоматически), одобрить и подтверждать каждую правку вручную или продолжить планирование. Сам план можно поправить руками: **Ctrl+G** откроет его в вашем редакторе."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "План не заменяет ревью",
      "text": "Одобренный план — договорённость о намерениях, а не гарантия результата. В деталях агент может от него отступить, поэтому diff всё равно читаете целиком. Как это делать быстро, разберём на этапе 4."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Когда план не нужен",
      "text": "Опечатка, строка лога, переименование переменной. Правило из документации Claude Code: если diff можно описать одним предложением, просите сделать сразу."
    }
  ],
  "practice": {
    "task": "Возьмите в своём проекте задачу на 30–60 минут, которая затрагивает больше одного файла. Включите plan mode, опишите задачу и получите план. Найдите в нём хотя бы одно допущение, с которым вы не согласны или которое не проговорено, исправьте его и только потом одобрите.",
    "done": [
      "в плане есть список файлов и способ проверки;",
      "вы изменили или уточнили хотя бы один пункт;",
      "до одобрения агент не изменил ни одного файла."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "shared-field",
        "prompt": "Нужно переименовать поле `userName` в ответе API. Им пользуются три сервиса, два из них поддерживают другие команды. С чего начнёте?",
