        "prompt": "Для какой задачи план до кода — лишняя трата времени?",
        "options": [
          {
            "id": "typo",
            "text": "Исправить опечатку в тексте кнопки."
          },
          {
            "id": "unfamiliar",
            "text": "Добавить кеширование в модуль, который вы видите впервые."
