          {
            "id": "vague",
            "text": "Опять не работает, исправь."
          },
          {
            "id": "caps",
            "text": "НЕПРАВИЛЬНО! Подумай ещё!"
          }
        ]
      },
      {
        "id": "think-deeper",
        "prompt": "Нужно спроектировать миграцию данных без простоя. Как попросить агента подумать глубже?",
        "options": [
          {
            "id": "ultrathink",
            "text": "Добавить в запрос слово `ultrathink`."
          },
          {
            "id": "think-hard",
            "text": "Написать «подумай очень хорошо»."
          },
          {
            "id": "repeat",
            "text": "Отправить запрос три раза подряд."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'iterations';
